def find_pair_diff(numbers: list[int], k: int) -> list[int]:
    i, j = 0, 1
    while i < len(numbers) and j < len(numbers):
        if i != j and numbers[j] - numbers[i] == k:
            return [i + 1, j + 1]
        elif numbers[j] - numbers[i] < k:
            j += 1
        else:
            i += 1
    return []
